import{at as e,n as t,rt as n,xt as r}from"./chunks/framework.DIOWbp6D.js";var i=JSON.parse(`{"title":"Handl ecosystem","description":"","frontmatter":{},"headers":[],"relativePath":"ecosystem/index.md","filePath":"ecosystem/index.md"}`),a={name:`ecosystem/index.md`};function o(t,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[e(`<h1 id="handl-ecosystem" tabindex="-1">Handl ecosystem <a class="header-anchor" href="#handl-ecosystem" aria-label="Permalink to “Handl ecosystem”">​</a></h1><p>Handl is a modular language infrastructure built around a categorical, runtime-independent IR. Its foundation is a closed arrow calculus with globular higher-categorical structure, allowing computation, laws, and transformations to share a common representation.</p><p>The ecosystem separates this foundation from the engines that process it, the abstractions built on top of it, and the environments in which it operates.</p><h2 id="_1-kernel" tabindex="-1">1. Kernel <a class="header-anchor" href="#_1-kernel" aria-label="Permalink to “1. Kernel”">​</a></h2><p>The Kernel defines Handl&#39;s computational foundation: its arrow calculus, IR, value representation, and language schema. It is a closed arrow calculus (LWY + Sanada) extended with graded effects and globular higher-categorical structure, where programs, laws, and transformations are all data.</p><p>The Kernel provides a stable foundation without prescribing a particular runtime or execution strategy. See <a href="/docs/paradigm/">the paradigm</a> for what the calculus buys you.</p><div class="eco-grid"><div class="eco-card"><strong>kernel</strong><p>The arrow-calculus substrate: language schema, tagged values, and extension ABI.</p><div class="eco-links"><a href="https://github.com/handl-lang/kernel">GitHub</a><a href="/kernel/">Docs</a></div></div></div><h2 id="_2-engines" tabindex="-1">2. Engines <a class="header-anchor" href="#_2-engines" aria-label="Permalink to “2. Engines”">​</a></h2><p>Independent components that process Handl representations. Engines can analyze, transform, compile, or execute the IR.</p><div class="eco-grid"><div class="eco-card"><strong>Compilation</strong><p>LLVM (native), Triton, CUDA emitters.</p><div class="eco-links"><a href="https://github.com/handl-lang/compile-llvm">compile-llvm</a> (private) <a href="https://github.com/handl-lang/compile-triton">compile-triton</a> (private) <a href="https://github.com/handl-lang/compile-cuda">compile-cuda</a> (private) </div></div><div class="eco-card"><strong>Execution</strong><p>Cranelift JIT, bytecode VM, and the tree-walk reference interpreter.</p><div class="eco-links"><a href="https://github.com/handl-lang/engine-exec-cranelift">engine-exec-cranelift</a><a href="https://github.com/handl-lang/engine-exec-bytecode">engine-exec-bytecode</a><a href="https://github.com/handl-lang/engine-exec-tree-walk">engine-exec-tree-walk</a></div></div><div class="eco-card"><strong>Transformation</strong><p>IR-to-IR rewriting, desugaring, and optimization.</p><div class="eco-links"><a href="https://github.com/handl-lang/engine-transform-rewrite">engine-transform-rewrite</a></div></div><div class="eco-card"><strong>Language processing</strong><p>Lexer, parser, typechecker, linter, and formatter engines.</p><div class="eco-links"><a href="https://github.com/handl-lang/engine-lex-pattern">engine-lex-pattern</a><a href="https://github.com/handl-lang/engine-parse-pratt">engine-parse-pratt</a><a href="https://github.com/handl-lang/engine-typecheck">engine-typecheck</a><a href="https://github.com/handl-lang/engine-lint">engine-lint</a><a href="https://github.com/handl-lang/engine-fmt">engine-fmt</a></div></div></div><p>Engines are interchangeable consumers and processors of the shared representation, not intrinsic parts of the Kernel.</p><h2 id="_3-libraries-lib" tabindex="-1">3. Libraries (<code>lib-*</code>) <a class="header-anchor" href="#_3-libraries-lib" aria-label="Permalink to “3. Libraries (lib-*)”">​</a></h2><p>Reusable Handl libraries (<code>.hnl</code>) providing foundational and domain-specific functionality, such as mathematics, strings, logic, and other utilities.</p><p>Libraries provide runtime-agnostic abstractions: the same APIs can be used across different execution environments, with runtime-specific implementations preserving compatible interfaces and semantics. This allows application code and higher-level libraries to remain independent of the underlying runtime.</p><h2 id="_4-kits-kit" tabindex="-1">4. Kits (<code>kit-*</code>) <a class="header-anchor" href="#_4-kits-kit" aria-label="Permalink to “4. Kits (kit-*)”">​</a></h2><p>Curated collections of libraries and components targeting particular environments or use cases, such as testing, server-side development, and web services. Kits provide ready-to-use environments by assembling compatible libraries, engines, and supporting components.</p><h2 id="_5-tools" tabindex="-1">5. Tools <a class="header-anchor" href="#_5-tools" aria-label="Permalink to “5. Tools”">​</a></h2><p>Developer utilities and generators that facilitate development and interoperability with external systems. SDK generators produce type-safe Handl APIs from existing interfaces.</p><div class="eco-grid"><div class="eco-card"><strong>sdkgen-python</strong><p>Python interoperability.</p><div class="eco-links"><a href="https://github.com/handl-lang/sdkgen-python">GitHub</a> (private) </div></div><div class="eco-card"><strong>sdkgen-c</strong><p>C interoperability, including libc, libcurl, and zlib.</p><div class="eco-links"><a href="https://github.com/handl-lang/sdkgen-c">GitHub</a> (private) </div></div><div class="eco-card"><strong>sdkgen-webidl</strong><p>Web APIs, including Fetch and Console.</p><div class="eco-links"><a href="https://github.com/handl-lang/sdkgen-webidl">GitHub</a> (private) </div></div><div class="eco-card"><strong>sdkgen-cli</strong><p>Type-safe APIs for spawning and interacting with CLI processes.</p><div class="eco-links"><a href="https://github.com/handl-lang/sdkgen-cli">GitHub</a> (private) </div></div></div><h2 id="_6-hosts" tabindex="-1">6. Hosts <a class="header-anchor" href="#_6-hosts" aria-label="Permalink to “6. Hosts”">​</a></h2><p>The distribution layer exposing Handl to users: the CLI and LSP.</p><div class="eco-grid"><div class="eco-card"><strong>host-cli</strong><p>The Handl command-line interface.</p><div class="eco-links"><a href="https://github.com/handl-lang/host-cli">GitHub</a></div></div><div class="eco-card"><strong>host-lsp</strong><p>The language server for editors.</p><div class="eco-links"><a href="https://github.com/handl-lang/host-lsp">GitHub</a> (private) </div></div></div><h2 id="_7-extensions" tabindex="-1">7. Extensions <a class="header-anchor" href="#_7-extensions" aria-label="Permalink to “7. Extensions”">​</a></h2><p>Editor integrations for development environments.</p><div class="eco-grid"><div class="eco-card"><strong>extension-vscode</strong><p>VS Code integration.</p><div class="eco-links"><a href="https://github.com/handl-lang/extension-vscode">GitHub</a> (private) </div></div><div class="eco-card"><strong>extension-neovim</strong><p>Neovim integration.</p><div class="eco-links"><a href="https://github.com/handl-lang/extension-neovim">GitHub</a> (private) </div></div></div><p>The Hosts and Extensions together form the integration layer that exposes Handl to users and development environments.</p><h2 id="_8-documentation" tabindex="-1">8. Documentation <a class="header-anchor" href="#_8-documentation" aria-label="Permalink to “8. Documentation”">​</a></h2><p>Aggregated documentation across the ecosystem.</p><div class="eco-grid"><div class="eco-card"><strong>docs</strong><p>This site: the hub for handl-lang documentation.</p><div class="eco-links"><a href="https://github.com/handl-lang/docs">GitHub</a></div></div></div><h2 id="_9-research" tabindex="-1">9. Research <a class="header-anchor" href="#_9-research" aria-label="Permalink to “9. Research”">​</a></h2><p>Research projects built on Handl.</p><div class="eco-grid"><div class="eco-card"><strong>MLOpt</strong><p>Optimization of existing machine learning models for embedded architectures.</p><div class="eco-links"><a href="https://github.com/handl-lang/mlopt">GitHub</a></div></div></div><h2 id="_10-products" tabindex="-1">10. Products <a class="header-anchor" href="#_10-products" aria-label="Permalink to “10. Products”">​</a></h2><p>Applications built on Handl. None yet; this section is a placeholder for what the ecosystem produces.</p>`,34)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};